#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, cap, rev;
};

class Dinic {
    vector<vector<Edge>> graph;
    vector<int> level, ptr;

public:
    explicit Dinic(int size) : graph(size), level(size), ptr(size) {}

    void addEdge(int u, int v, int cap) {
        Edge forward{v, cap, static_cast<int>(graph[v].size())};
        Edge reverse{u, 0, static_cast<int>(graph[u].size())};
        graph[u].push_back(forward);
        graph[v].push_back(reverse);
    }

    bool bfs(int source, int sink) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[source] = 0;
        q.push(source);

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            for (const Edge& edge : graph[u]) {
                if (edge.cap > 0 && level[edge.to] == -1) {
                    level[edge.to] = level[u] + 1;
                    q.push(edge.to);
                }
            }
        }

        return level[sink] != -1;
    }

    int dfs(int u, int sink, int flow) {
        if (u == sink) return flow;

        for (int& i = ptr[u]; i < static_cast<int>(graph[u].size()); ++i) {
            Edge& edge = graph[u][i];

            if (edge.cap == 0 || level[edge.to] != level[u] + 1)
                continue;

            int pushed = dfs(edge.to, sink, min(flow, edge.cap));
            if (pushed == 0) continue;

            edge.cap -= pushed;
            graph[edge.to][edge.rev].cap += pushed;
            return pushed;
        }

        return 0;
    }

    int maxFlow(int source, int sink) {
        int result = 0;

        while (bfs(source, sink)) {
            fill(ptr.begin(), ptr.end(), 0);
            while (int pushed = dfs(source, sink, INT_MAX))
                result += pushed;
        }

        return result;
    }
};

