    vec <Edge> adj[N];
} graph;

void input() {
    cin >> n >> m;
}

int id(int i, int j) {
    return i * m + j + 1;
}

void add_edge(int u, int v, int c) {
    graph.adj[u].pb({v, c, 0, len(graph.adj[v])});
    graph.adj[v].pb({u, c, c, len(graph.adj[u]) - 1});
}

bool bfs() {
    queue <int> q; 
    q.push(s);
    while(!q.empty()) {
        int u = q.front(); q.pop();
        for(Edge e: graph.adj[u]) {
            int v = e.ver;
            if(!graph.lev[v] && e.flw < e.cap) {
                graph.lev[v] = graph.lev[u] + 1;
                q.push(v);
            }
        }
    }
    return graph.lev[t];
}

int dfs(int u, int flow) {
    if(u == t) {
        return flow;
    }
    for(int &i = graph.ptr[u]; i < len(graph.adj[u]); ++i) {
        Edge &e = graph.adj[u][i];
        Edge &r = graph.adj[e.ver][e.rev];
        int v = e.ver;
        if(e.cap == e.flw || graph.lev[v] != graph.lev[u] + 1) {
            continue;
        }
        int f = dfs(v, min(flow, e.cap - e.flw));
        if(!f) {
            continue;
        }
        e.flw += f;
        r.flw -= f;
        return f;
    }
    return 0;
}

int dinic() {
    int res = 0;
    while(true) {
        fill(graph.lev, graph.lev + N, 0);
        fill(graph.ptr, graph.ptr + N, 0);
        graph.lev[s] = 1;
        if(!bfs()) {
            break;
        }
        while(int flow = dfs(s, 1)) {
            res += flow;
        }
    }
    return res;
}

void solve() {
    if(min(n, m) >= 20) {
        cout << 1ll * n * m / 2 * 2 << "\n";
        return;
    }
    s = 0, t = N - 1;
    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < m; ++j) {
            if(i + j & 1) {
                for(pii p: adj) {
                    int I = i + p.xx;
                    int J = j + p.yy;
                    if(I < 0 || J < 0 || I >= n || J >= m) {
                        continue;
                    } else {
                        add_edge(id(i, j), id(I, J), 1);
                    }
                }
                add_edge(s, id(i, j), 1);
            } else {
                add_edge(id(i, j), t, 1);
            }
        }
    }
    cout << 2 * dinic() << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);
    input();
    solve();
}
